33	template<typename ElementAccum, typename Params, int kBlockM, bool Is_even_MN>
34	__forceinline__ __device__ auto get_lse_tile(const Params &params, const int bidb, const int bidh, const int m_block, const BlockInfo</*Varlen=*/!Is_even_MN> &binfo) {
35	        // When params.unpadded_lse is false, LSE is written as (b, h, seqlen_q) - this is non-variable seqlen path.
36	        // Otherwise, when params.seqlenq_ngroups_swapped is true, it is written as (h, seqlen_q, b) to account for seqlen_q <-> h swapping trick.
37	        // Otherwise, it's written as (h, b, seqlen_q).
38	        const bool varlen_q = params.unpadded_lse && !params.seqlenq_ngroups_swapped;
39	        auto lse_offset = varlen_q ? binfo.q_offset(params.seqlen_q, 1, bidb) : 0;
40	        auto gmem_ptr_lse = make_gmem_ptr(reinterpret_cast<ElementAccum*>(params.softmax_lse_ptr) + lse_offset);
41	
42	        auto lse_shape = varlen_q ? make_shape(1, params.h, params.total_q) : make_shape(params.b, params.h, params.seqlen_q);
43	        auto lse_stride = params.seqlenq_ngroups_swapped ? make_stride(1, params.seqlen_q * params.b, params.b) : (
44	            params.unpadded_lse ? make_stride(params.h * params.total_q, params.total_q, 1) :  make_stride(params.h * params.seqlen_q, params.seqlen_q, 1)
45	            );
46	
47	        auto lse_layout = make_layout(lse_shape, lse_stride);
48	        Tensor mLSE = make_tensor(gmem_ptr_lse, lse_layout);
49	        auto mLSE_slice = varlen_q ? mLSE(0, bidh, _) : mLSE(bidb, bidh, _);
50	        return local_tile(mLSE_slice, Shape<Int<kBlockM>>{}, make_coord(m_block));
51	}
